// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"fully-diluted-valuation":{"slug":"fully-diluted-valuation","cat":"basics","en":"Fully diluted valuation (FDV)","contentLocale":"en","term":"Fully diluted valuation (FDV)","aka":["FDV","fully diluted market cap"],"short":"Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply.","body":[["Many tokens launch with only a small share of supply ",["circulating","circulating-supply"],". The rest is reserved for the team, early investors, ecosystem funds or future rewards and is released over months or years. ",["Market cap","market-capitalization"]," only counts the circulating part, so it can make a project look smaller than it really is."],"FDV shows the size the project would have at today's price once every token is out. The ratio between market cap and FDV tells you how much new supply is still coming. If circulating supply is 15 percent of the total, the remaining 85 percent will enter the market over time, and someone has to buy those tokens for the price to hold.","Data sites calculate FDV with either maximum supply or total supply, and some tokens have no maximum at all, so compare like with like. FDV is not a price target; it is a tool for spotting heavy future dilution."],"example":["Suppose a new token trades at 0.50 ",["USDT","usdt"]," with 200 million tokens circulating and a maximum supply of 1 billion. Its market cap is 100 million USDT, but its FDV is 500 million USDT. Only 20 percent of the supply is out. If the other 800 million tokens unlock over three years, roughly 22 million tokens enter circulation each month on average, and at today's price that is about 11 million USDT of new supply monthly."],"mistakes":["Looking only at market cap on a low-float token and missing that FDV is several times larger.","Treating FDV as a forecast of where the price will go.","Comparing one project's FDV based on maximum supply with another's based on total supply."],"faq":[{"q":"Is a high FDV bad?","a":"Not by itself. A high FDV compared with market cap means a lot of supply is still to come, which can create selling pressure if demand does not keep up."},{"q":"What is a low float token?","a":"A token where only a small percentage of total supply is circulating. These often have a large gap between market cap and FDV."},{"q":"Does Bitcoin have an FDV?","a":"Yes. It is the price multiplied by 21 million BTC. Because most bitcoins are already mined, Bitcoin's FDV is close to its market cap."}],"title":"What is FDV (fully diluted valuation) in crypto?","description":"Learn what fully diluted valuation means, how it differs from market cap and how to spot heavy token dilution.","related":[["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."],["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens."],["token-unlock","Token unlock","A token unlock is a scheduled event when previously locked tokens, usually held by the team, investors or a treasury, become free to transfer and sell, increasing circulating supply."],["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"mining":{"slug":"mining","cat":"basics","en":"Crypto mining","contentLocale":"en","term":"Crypto mining","aka":["mining","bitcoin mining"],"short":"Crypto mining is the process of using specialised computers to secure a proof-of-work blockchain by adding new blocks, in exchange for newly issued coins and transaction fees.","body":[["Miners collect ",["pending transactions","mempool"],", build a candidate block and then race to find a hash that meets the network's difficulty target. The winner broadcasts the block, other nodes verify it, and the miner receives the block reward plus fees. On ",["Bitcoin","bitcoin"]," that reward is 3.125 BTC per block since the April 2024 halving."],["Mining today is an industrial business. Bitcoin is mined with ASICs, chips built for a single hashing algorithm. Profitability depends on the coin price, the machine's efficiency, the electricity price and the network's total ",["hash rate","hash-rate"],". When many new machines join, each miner's share of rewards shrinks."],"Because a single miner might go months without finding a block, most join mining pools that combine hash power and share rewards in proportion to the work submitted. Be careful with cloud mining offers that promise fixed daily returns; many are scams, and legitimate ones still carry the same price and difficulty risks."],"example":["Suppose a miner runs one ASIC that earns about 0.00012 BTC per day at current difficulty. At an illustrative BTC price of 70,000 ",["USDT","usdt"],", that is 8.40 USDT per day. The machine uses 3.2 kWh per hour, or 76.8 kWh a day. At 0.08 USDT per kWh, electricity costs about 6.14 USDT, leaving roughly 2.26 USDT of daily gross profit before hardware costs, pool fees and repairs. If electricity cost 0.12 USDT per kWh, the miner would make a loss of about 0.82 USDT a day."],"mistakes":["Calculating profit with today's difficulty and price as if they will never change.","Paying for cloud mining contracts that promise guaranteed daily income.","Forgetting cooling, noise, hardware wear and local electricity rules when mining at home."],"faq":[{"q":"Is crypto mining still profitable?","a":"It depends on electricity costs, hardware efficiency, coin price and network difficulty. Large operations with cheap power have a big advantage over home miners."},{"q":"Can you mine Ethereum?","a":"No. Ethereum stopped mining when it moved to proof of stake in September 2022. Validators now secure it by staking ETH."},{"q":"What is a mining pool?","a":"A mining pool combines the hash power of many miners and splits rewards according to each member's contributed work, giving smaller miners steadier payouts."}],"title":"What is crypto mining? Meaning and how it works","description":"Learn how crypto mining works, what drives mining profit, why pools exist and what to watch for with cloud mining.","related":[["proof-of-work","Proof of work (PoW)","Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward."],["hash-rate","Hash rate","Hash rate is the total computing power that miners use to secure a proof-of-work blockchain, measured in hashes per second."],["bitcoin-halving","Bitcoin halving","A Bitcoin halving is a pre-programmed event, roughly every four years, that cuts the number of new bitcoins paid to miners for each block by 50 percent."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"validator":{"slug":"validator","cat":"basics","en":"Validator","contentLocale":"en","term":"Validator","aka":["validator node","staking node"],"short":"A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid.","body":["Validators replace miners in proof-of-stake networks. They must stay online, run up-to-date software and sign blocks correctly. In return they earn rewards from new issuance and transaction fees. If they go offline they may miss rewards, and if they sign conflicting messages they can be slashed, losing part of their stake.",["Each network sets its own rules. On ",["Ethereum","ethereum"],", running a solo validator requires 32 ETH and a reliable machine. Other chains such as Solana or Cosmos-based networks let holders delegate coins to a validator, which then shares rewards after taking a commission."],["When you stake on an exchange or through a ",["liquid staking","liquid-staking"]," protocol, a validator is still doing the work in the background. Choosing who runs that validator matters: uptime, commission, slashing history and how concentrated the stake already is all affect your rewards and the health of the network."]],"example":["Suppose you delegate 1,000 SOL to a validator. The network's gross ",["staking","staking"]," reward works out to about 7 percent a year for that validator, and it charges a 5 percent commission on rewards. Gross rewards would be 70 SOL, the validator keeps 3.5 SOL, and you receive about 66.5 SOL over the year. If the validator were offline for part of the year, your actual rewards would be lower."],"mistakes":["Choosing a validator only by the lowest commission without checking uptime and reliability.","Thinking delegated coins are sent to the validator; on most delegation systems they stay in your account but are locked.","Running a solo validator without backup monitoring and getting penalised for downtime."],"faq":[{"q":"How much ETH do you need to be a validator?","a":"A solo Ethereum validator needs 32 ETH. With less, you can use pooled staking, an exchange product or a liquid staking protocol."},{"q":"What is the difference between a validator and a miner?","a":"A miner secures a proof-of-work chain with computing power. A validator secures a proof-of-stake chain with staked coins."},{"q":"What happens if a validator is slashed?","a":"Part of the validator's stake is destroyed and it may be removed from the active set. Delegators to that validator can also lose a share, depending on the network's rules."}],"title":"What is a validator in crypto? Meaning explained","description":"Learn what a blockchain validator does, how delegation and commission work and what slashing means for stakers.","related":[["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules."],["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["restaking","Restaking","Restaking is reusing already staked ETH, or a liquid staking token, to also secure additional services, earning extra rewards in exchange for extra slashing and smart contract risk."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"trading-pair":{"slug":"trading-pair","cat":"trading","en":"Trading pair","contentLocale":"en","term":"Trading pair","aka":["pair","market pair","currency pair"],"short":"A trading pair is two assets that can be exchanged for each other on a market, such as BTC/USDT, where the first is the base asset you buy or sell and the second is the quote asset used to price it.","body":[["In ",["BTC","bitcoin"],"/",["USDT","usdt"],", BTC is the base and USDT is the quote. A price of 65,000 means one BTC costs 65,000 USDT. Buying the pair means buying BTC and paying USDT; selling it means selling BTC and receiving USDT."],["Most crypto volume is quoted in ",["stablecoins","stablecoin"]," such as USDT and ",["USDC","usdc"],". Exchanges also list pairs against BTC, ",["ETH","ethereum"],", their own tokens and fiat currencies like EUR. The same coin can have very different ",["liquidity","liquidity"]," on different pairs, so a coin that trades well against USDT may have a wide spread against BTC."],"If the pair you want does not exist, you may need two trades, for example selling coin A for USDT and then buying coin B with USDT. That means paying fees twice. Some exchanges offer a convert feature that does the routing for you, but the price may include a spread, so compare it with the order book."],"example":"Suppose you hold 0.02 BTC and want SOL, but the exchange has no SOL/BTC pair. You sell 0.02 BTC on BTC/USDT at 70,000, receiving 1,400 USDT minus a 0.1 percent fee, so 1,398.60 USDT. Then you buy SOL on SOL/USDT at 140 USDT, getting 9.99 SOL before the second fee and about 9.98 SOL after it. In total you paid roughly 2.8 USDT in fees across both trades.","mistakes":["Mixing up base and quote and entering an order for the wrong amount.","Trading a coin on a thin pair when a more liquid pair is available.","Forgetting that a two-step route through USDT costs two fees and two spreads."],"faq":[{"q":"What does BTC/USDT mean?","a":"It is the market where BTC is bought and sold using USDT. The price shows how many USDT one BTC costs."},{"q":"What is the base and quote currency?","a":"The base is the first asset in the pair, the one being bought or sold. The quote is the second asset, used to express the price."},{"q":"Why do most pairs use USDT?","a":"USDT is the most widely used stablecoin on exchanges, so USDT pairs tend to have the most liquidity and the tightest spreads."}],"title":"What is a trading pair in crypto? Base and quote","description":"Learn how crypto trading pairs work, what base and quote mean and why the pair you choose affects liquidity and fees.","related":[["spot-trading","Spot trading","Spot trading is buying or selling a cryptocurrency for immediate delivery at the current market price, so you actually own the coins once the trade is filled."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Your first spot trade: from 100 to 0.002 BTC"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"oco-order":{"slug":"oco-order","cat":"trading","en":"OCO order (one-cancels-the-other)","contentLocale":"en","term":"OCO order (one-cancels-the-other)","aka":["OCO","one cancels the other"],"short":"An OCO (one-cancels-the-other) order pairs two orders, typically a take-profit and a stop-loss, so that when one of them executes, the other is automatically cancelled.","body":["OCO solves a simple problem. If you place a take-profit limit and a separate stop-loss on the same coins, and one fills, the other might later fill too and open an unwanted position, or the exchange might reject it for lack of balance. With OCO, the exchange links them and cancels the leftover one for you.",["A typical spot OCO for a long position is a sell limit above the price as the take-profit and a sell ",["stop-limit","stop-limit-order"]," or stop-market below as the stop-loss. On futures, the same idea is often built into the take-profit and stop-loss fields attached to a position."],"OCO is useful when you cannot watch the market, because both exits are planned in advance. Check how your exchange implements it: some reserve the full balance for both legs, and the stop leg may be a stop-limit that can fail to fill in a sharp move."],"example":["Suppose you hold 0.5 ",["BTC","bitcoin"]," bought at 60,000 ",["USDT","usdt"],". You place an OCO sell for 0.5 BTC with a limit at 66,000 and a stop at 57,000. If BTC rises to 66,000, the limit fills for a gain of 3,000 USDT and the stop is cancelled. If BTC falls to 57,000 first, the stop triggers for a loss of about 1,500 USDT and the take-profit is cancelled. Your reward-to-risk on the trade is 2 to 1."],"mistakes":["Placing two separate exit orders instead of an OCO, then accidentally leaving one open after the other fills.","Not knowing whether the stop leg is a stop-limit, which can fail to fill in a crash.","Setting the take-profit and stop so close together that normal volatility hits one at random."],"faq":[{"q":"What does OCO mean in crypto?","a":"OCO stands for one-cancels-the-other, two linked orders where filling one cancels the other."},{"q":"Can I use OCO for buying?","a":"Yes. A buy OCO can combine a buy limit below the price with a buy stop above it, so you enter on either a dip or a breakout."},{"q":"Do all exchanges support OCO orders?","a":"Many major exchanges do on spot, but naming and options vary, and some only offer linked take-profit and stop-loss on futures positions."}],"title":"What is an OCO order? One-cancels-the-other explained","description":"Learn how an OCO order links a take-profit and a stop-loss so that one cancels the other, with a worked example.","related":[["take-profit","Take-profit order","A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["risk-reward-ratio","Risk-reward ratio","The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Market, limit, cancel: what does each one solve?"},"coin":null,"tool":null,"cta":false},"post-only-order":{"slug":"post-only-order","cat":"trading","en":"Post-only order","contentLocale":"en","term":"Post-only order","aka":["post only","maker-only order"],"short":"A post-only order is a limit order that is only allowed to add liquidity to the order book; if it would fill immediately against an existing order, the exchange cancels or adjusts it instead.","body":[["A normal ",["limit order","limit-order"]," placed at or across the best price fills straight away and pays the ",["taker fee","maker-taker-fees"],". Post-only prevents that. It guarantees that if your order executes, it does so as a maker, paying the lower maker fee or, at some fee tiers, earning a rebate."],"This matters for active traders and market makers whose costs add up over many trades. It also protects you from accidentally crossing the spread when the price moves between setting your order and submitting it.",["The trade-off is that your order may be rejected or never filled when the market is moving. Some exchanges simply cancel a post-only order that would take ",["liquidity","liquidity"],", while others reprice it to the best available maker price. Check your exchange's rules and fee schedule, as maker and taker fees differ by platform and ",["VIP level","vip-tier"],"."]],"example":["Suppose you trade 200,000 ",["USDT","usdt"]," of volume a month. If your exchange charges 0.02 percent maker and 0.05 percent taker on futures, all-taker trading costs 100 USDT a month while all-maker trading costs 40 USDT. Using post-only orders for most entries could save around 60 USDT a month, or 720 USDT a year, as long as you still get filled at the prices you want."],"mistakes":["Being surprised when a post-only order is cancelled because it would have filled immediately.","Using post-only when you urgently need to exit a position.","Assuming maker fees are the same on every exchange or account tier."],"faq":[{"q":"Why was my post-only order cancelled?","a":"Because at the moment it arrived, it would have matched an existing order and paid taker fees. The exchange cancelled it to keep it maker-only."},{"q":"Does post-only guarantee maker fees?","a":"Yes, if it fills, it fills as a maker. It does not guarantee that it will fill."},{"q":"Is post-only the same as a limit order?","a":"It is a type of limit order with an extra rule that it must not take liquidity."}],"title":"What is a post-only order? Meaning in crypto trading","description":"Learn what a post-only order is, how it guarantees maker fees and why exchanges cancel it when it would fill instantly.","related":[["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force is an order setting that controls how long an order stays active and how it handles partial fills, with common options GTC (good till cancelled), IOC (immediate or cancel) and FOK (fill or kill)."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Market, limit, cancel: what does each one solve?"},"coin":null,"tool":"/rates","cta":false},"maker-taker-fees":{"slug":"maker-taker-fees","cat":"trading","en":"Maker and taker fees","contentLocale":"en","term":"Maker and taker fees","aka":["maker fee","taker fee","maker/taker"],"short":"Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it.","body":[["A maker order is one that does not fill immediately. It rests in the ",["order book","order-book"]," and waits for someone else to trade against it, so it makes the market deeper. A typical maker order is a ",["limit buy","limit-order"]," below the current price or a limit sell above it."],["A taker order fills right away against orders that are already in the book. Market orders are always takers, and a limit order priced across the spread also fills as a taker. Because takers consume ",["liquidity","liquidity"],", most exchanges charge them more."],["Fees are a percentage of the trade value, not of your profit. They differ by exchange, by product (spot versus futures) and by your ",["fee tier","vip-tier"],", which usually depends on 30-day ",["trading volume","trading-volume"]," or token holdings. Some venues pay a small rebate to makers on certain markets. Check the fee schedule of your own exchange before comparing costs."]],"example":["Suppose your exchange charges 0.02% for makers and 0.05% for takers on futures. You open a 20,000 ",["USDT","usdt"]," position with a market order, paying 20,000 × 0.05% = 10 USDT. If you had used a limit order that rested in the book, the fee would be 20,000 × 0.02% = 4 USDT. Closing the same size again as a taker adds another 10 USDT, so a round trip costs 20 USDT as a taker versus 8 USDT as a maker. Over a hundred trades, that gap becomes 1,200 USDT."],"mistakes":["Assuming every limit order is a maker order, when a limit priced through the spread fills instantly and pays the taker fee.","Calculating fees on margin instead of on the full leveraged position size.","Ignoring the closing fee and only counting the cost of opening a trade."],"faq":[{"q":"Why are taker fees higher than maker fees?","a":"Makers add orders that others can trade against, which keeps spreads tight. Exchanges reward that with a lower rate and charge takers more for using the existing liquidity."},{"q":"How do I make sure I pay the maker fee?","a":"Use a post-only limit order. If it would fill immediately as a taker, the exchange cancels or adjusts it instead of executing it."},{"q":"Are maker and taker fees the same on every exchange?","a":"No. Rates depend on the exchange, the product and your fee tier, and they change over time, so always check the current fee page."}],"title":"What are maker and taker fees? Crypto fees explained","description":"Learn the difference between maker and taker fees, how they are calculated on crypto exchanges and how to pay less per trade.","related":[["post-only-order","Post-only order","A post-only order is a limit order that is only allowed to add liquidity to the order book; if it would fill immediately against an existing order, the exchange cancels or adjusts it instead."],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher."],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["vip-tier","VIP fee tier","A VIP fee tier is an exchange level that gives lower trading fees and extra benefits to users who trade high volume or hold large balances."],["referral-code","Referral code (fee rebate)","A referral code is a code you enter when signing up to an exchange that links your account to a referrer and can give you a discount or rebate on trading fees."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Why isn't the price on screen my fill price?"},"coin":null,"tool":"/rates","cta":true},"maintenance-margin":{"slug":"maintenance-margin","cat":"derivatives","en":"Maintenance margin","contentLocale":"en","term":"Maintenance margin","aka":["MM","maintenance margin rate","MMR"],"short":"Maintenance margin is the minimum collateral you must keep in a leveraged position; if your margin falls below it, the position is liquidated.","body":[["After you open a position, your margin changes with ",["unrealized profit and loss","unrealized-pnl"],". The exchange compares it with a required minimum, the maintenance margin, which is a percentage of the position value. For major pairs at small sizes this rate is often well under 1%, but it rises for larger positions and riskier coins."],["When your margin balance drops to the maintenance level, ",["liquidation","liquidation"]," starts. Exchanges measure this with the ",["mark price","mark-price"],", not the ",["last traded price","last-price"],", to avoid liquidations caused by brief spikes. Many platforms show a margin ratio; when it approaches 100%, you are close to liquidation."],["You can move away from the maintenance level by adding margin, reducing the position, or lowering exposure. Because maintenance margin rates are tiered by ",["position size","position-sizing"],", a large position can have a ",["liquidation price","liquidation-price"]," closer to entry than you might expect. Check the risk limit or margin tier table on your exchange."]],"example":"Suppose you hold a 20,000 USDT position with 2,000 USDT of margin (10x) and the maintenance margin rate is 0.5%. The required minimum is 20,000 × 0.5% = 100 USDT. Your unrealized loss can grow to about 1,900 USDT before liquidation, ignoring fees. For a long, that is a 9.5% price drop. A larger position with a 2% rate would require 400 USDT and leave only 1,600 USDT of room.","mistakes":["Watching only the last price, when the exchange uses the mark price for maintenance checks.","Assuming the maintenance rate is the same for every position size.","Waiting until the margin ratio is near 100% before adding collateral."],"faq":[{"q":"What happens if my margin falls below maintenance margin?","a":"The exchange's liquidation engine takes over the position and closes it, fully or in steps, and any remaining margin may be lost."},{"q":"How do I avoid hitting maintenance margin?","a":"Use lower leverage, size positions sensibly, set a stop-loss well before the liquidation price, and add margin early if needed."}],"title":"What is maintenance margin? Crypto futures explained","description":"Learn what maintenance margin is, how it sets your liquidation point and why the required rate rises with position size.","related":[["initial-margin","Initial margin","Initial margin is the amount of collateral you must post to open a leveraged position, usually equal to the position value divided by your leverage."],["liquidation-price","Liquidation price","The liquidation price is the mark price at which your leveraged position will be forcibly closed because your margin would fall to the maintenance margin level."],["margin-call","Margin call","A margin call is a warning that your collateral has fallen close to the minimum required for a leveraged position, so you need to add margin or reduce the position to avoid liquidation."],["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price."]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"Why you can be closed out before your margin hits zero"},"coin":null,"tool":"/liquidations","cta":false},"reduce-only-order":{"slug":"reduce-only-order","cat":"derivatives","en":"Reduce-only order","contentLocale":"en","term":"Reduce-only order","aka":["reduce only","close-only order"],"short":"A reduce-only order is a futures order setting that can only shrink or close an existing position and will never open a new one or increase it.","body":[["Normally a sell order on a futures market can either close a long or open a new short. If you place a 2 ",["BTC","bitcoin"]," sell to close a 1 BTC long, the extra 1 BTC opens a short you never intended. Ticking reduce-only prevents that: the exchange only executes the part that reduces your current position."],"Reduce-only is mainly used for take-profit and stop-loss orders, and for limit orders placed in advance to scale out of a trade. If your position is closed by another order first, any remaining reduce-only orders are cancelled or rejected instead of opening something new.",["Many exchanges set take-profit and stop-loss orders attached to a position as reduce-only by default, but standalone limit or conditional orders may not be. In hedge mode, where you can hold a long and a short on the same ",["contract","smart-contract"],", closing orders work slightly differently. Check how your exchange labels and handles it."]],"example":["Suppose you are long 0.6 BTC and place two take-profit limit sells of 0.4 BTC each, at 68,000 and 70,000 ",["USDT","usdt"],", both reduce-only. The first fills and your position drops to 0.2 BTC. When price reaches 70,000, the second order only sells 0.2 BTC and closes the position. Without reduce-only, it would sell 0.4 BTC and leave you with an unwanted 0.2 BTC short."],"mistakes":["Placing take-profit orders larger than the position without reduce-only, and ending up short.","Assuming every stop or limit order is reduce-only by default.","Forgetting that reduce-only orders cannot be used to open a position later."],"faq":[{"q":"What does reduce-only mean on Binance or Bybit?","a":"It means the order can only reduce or close your current position. Many exchanges, including Binance and Bybit, offer it as a checkbox on futures orders."},{"q":"Why was my reduce-only order rejected?","a":"Usually because there was no open position in that direction, or the position was already smaller than the order."}],"title":"What is a reduce-only order in crypto futures?","description":"Learn what a reduce-only order does, why it stops take-profit orders from opening new positions and when to use it.","related":[["take-profit","Take-profit order","A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market."],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price."],["long-and-short","Long and short positions","A long position profits when an asset's price rises, and a short position profits when its price falls."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit and stop-loss are plans, not insurance"},"coin":null,"tool":null,"cta":false},"wallet-address":{"slug":"wallet-address","cat":"wallets-security","en":"Wallet address","contentLocale":"en","term":"Wallet address","aka":["crypto address","deposit address","receiving address"],"short":"A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly.","body":[["Address formats depend on the ",["blockchain","blockchain"],". ",["Bitcoin","bitcoin"]," addresses often start with bc1, 1 or 3. ",["Ethereum","ethereum"]," and other EVM chains such as BNB Smart Chain, Arbitrum and Base use addresses that start with 0x. Tron addresses start with T, and Solana addresses are long base58 strings."],"An address is only valid on the network it belongs to. The same 0x address can exist on several EVM chains, which is why an exchange asks you to pick a network on top of the address. Sending to the right address on the wrong network can make funds hard or impossible to recover.","Blockchain transfers cannot be reversed. Copy addresses with the copy button or a QR code, then check the first and last several characters before you confirm."],"example":["Say you withdraw 1,000 ",["USDT","usdt"]," from an exchange to your own wallet. Your wallet shows an address starting with T, so you choose the TRC-20 network on the exchange and paste the address. You first send 20 USDT as a test, see it arrive in your wallet, and then send the remaining 980 USDT. The test costs one extra network fee, but it confirms the address and network before the larger amount moves."],"mistakes":["Copying an address from your transaction history, where a look-alike poisoned address may be waiting.","Choosing a network that the receiving wallet or exchange does not support.","Typing an address by hand instead of copying it or scanning its QR code."],"faq":[{"q":"Can I reuse the same wallet address?","a":"Yes, an address can receive many times. Some Bitcoin wallets generate a new address for each payment to improve privacy, but older ones still work."},{"q":"Is it safe to share my wallet address?","a":"Yes. Others can only send to it and view its public history; they cannot spend from it."}],"title":"What is a wallet address? Crypto address explained","description":"Learn what a crypto wallet address is, how formats differ by chain, and how to check an address before sending.","related":[["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one."],["memo-tag","Memo / destination tag","A memo or destination tag is an extra code attached to a transfer that tells an exchange which customer account should receive a deposit sent to a shared address."],["address-poisoning","Address poisoning","Address poisoning is a scam where an attacker sends a tiny or zero-value transfer from an address that looks like one you use, hoping you later copy that fake address from your transaction history."],["withdrawal-whitelist","Withdrawal whitelist","A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"phishing":{"slug":"phishing","cat":"wallets-security","en":"Phishing","contentLocale":"en","term":"Phishing","aka":["phishing scam","phishing attack","wallet drainer"],"short":"Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds.","body":[["Crypto phishing comes through fake websites with near-identical domains, search ads, emails, SMS, social media replies, fake support accounts and direct messages offering airdrops. The goal is either to collect what you type, such as passwords, ",["2FA","two-factor-authentication"]," codes or seed phrases, or to get you to connect a wallet and sign a malicious approval."],["Signs to check: an urgent deadline, a request for your ",["seed phrase","seed-phrase"],", a domain that is slightly different, a support agent who contacts you first, or a wallet pop-up asking to approve unlimited spending or sign a message you do not understand."],["Practical defences are simple. Bookmark official sites, open the app directly rather than clicking links, set an ",["anti-phishing code","anti-phishing-code"],", use a ",["withdrawal whitelist","withdrawal-whitelist"],", and read every wallet request before signing."]],"example":["Imagine you search for your wallet's website and click the first result, which is an ad. The page asks you to enter your 12-word phrase to fix a sync error. A real wallet would never ask for this. Had you entered it, a wallet holding 3,000 ",["USDC","usdc"]," and 0.6 ",["ETH","ethereum"]," would be emptied within minutes. Instead, you close the tab and open the bookmarked official site, which shows no error at all."],"mistakes":["Trusting a link because it appeared at the top of search results or in a verified-looking account.","Replying to a support agent who messaged you first on Telegram, Discord or X.","Signing a wallet request to claim a free airdrop without reading what it approves."],"faq":[{"q":"What should I do if I clicked a phishing link?","a":"If you only opened the page, close it. If you entered a password or code, change your password and check your account; if you entered a seed phrase or signed an approval, move remaining funds to a new wallet and revoke approvals."},{"q":"How can I tell if a crypto site is fake?","a":"Check the exact domain spelling, use bookmarks, and be suspicious of any page that asks for your seed phrase or creates urgency."}],"title":"What is phishing in crypto? How to spot it","description":"Learn how crypto phishing works, the warning signs of fake sites and messages, and simple habits that protect you.","related":[["anti-phishing-code","Anti-phishing code","An anti-phishing code is a personal word or phrase you set in your exchange account that the exchange includes in its genuine emails, so you can spot fake messages that do not contain it."],["seed-phrase","Seed phrase (recovery phrase)","A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds."],["token-approval","Token approval (allowance)","A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi."],["address-poisoning","Address poisoning","Address poisoning is a scam where an attacker sends a tiny or zero-value transfer from an address that looks like one you use, hoping you later copy that fake address from your transaction history."],["pig-butchering-scam","Pig-butchering scam","A pig-butchering scam is a long-con fraud where a stranger builds trust over weeks, often as a friend or romantic interest, then steers you into a fake crypto investment platform and takes everything you deposit."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Find the real door first: don't open an account on a fake platform"},"coin":null,"tool":null,"cta":false},"proof-of-reserves":{"slug":"proof-of-reserves","cat":"wallets-security","en":"Proof of reserves","contentLocale":"en","term":"Proof of reserves","aka":["PoR","proof of reserve","reserve audit"],"short":"Proof of reserves is a report in which a crypto exchange shows that the assets it holds in wallets it controls are at least equal to the balances it owes its customers.","body":["Most proof-of-reserves reports have two parts. First, the exchange shows which on-chain wallets it controls and how much each holds. Second, it shows total customer liabilities, often with a Merkle tree so each user can check that their own balance was included. Some exchanges add zk-proofs to show no negative balances were hidden.","The resulting reserve ratio compares assets with liabilities for each coin. A ratio of 100 percent or more means assets cover customer balances at that moment.","Proof of reserves has limits. It is a snapshot at one time, it may not show debts owed elsewhere by the company, and the quality depends on who checks it. A report reviewed by an independent auditor or verifiable on-chain is stronger than a simple self-published chart."],"example":["Suppose an exchange reports customer ",["USDT","usdt"]," balances of 2.0 billion and USDT held in its disclosed wallets of 2.1 billion. The reserve ratio is 2.1 divided by 2.0, or 105 percent. You then use the exchange's verification tool, enter your record ID, and confirm your 1,250 USDT balance is in the Merkle tree. That tells you your balance was counted, but not whether the company has other loans outside the report."],"mistakes":["Reading a reserve ratio above 100 percent as proof the exchange cannot fail.","Looking only at the total ratio and ignoring individual coins with lower coverage.","Assuming an old report reflects today's position."],"faq":[{"q":"Is proof of reserves the same as an audit?","a":"No. A full financial audit also reviews liabilities, debts and controls. Proof of reserves focuses on customer balances and the assets that back them."},{"q":"How do I verify my balance in proof of reserves?","a":"Most exchanges provide a verification page where you see your record ID and check that your balance is included in the Merkle tree for that snapshot."}],"title":"What is proof of reserves? How exchanges prove it","description":"What proof of reserves is, how the reserve ratio and Merkle tree checks work, and what the report cannot show.","related":[["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["insurance-fund","Insurance fund","An insurance fund is a reserve an exchange keeps to cover losses when liquidated positions cannot be closed at a price good enough to repay what they owe."],["on-chain-analysis","On-chain analysis","On-chain analysis is the study of public blockchain data, such as transactions, wallet balances and exchange flows, to understand how a network is used and how holders behave."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Find the real door first: don't open an account on a fake platform"},"coin":null,"tool":"/exchanges","cta":false},"crypto-earn":{"slug":"crypto-earn","cat":"exchange-features","en":"Crypto Earn (savings products)","contentLocale":"en","term":"Crypto Earn (savings products)","aka":["Earn","crypto savings","simple earn","flexible savings"],"short":"Crypto Earn refers to exchange savings products that pay you a yield for depositing crypto, either flexible with withdrawal anytime or locked for a fixed term.","body":["Most large exchanges group these under a name like Earn or Simple Earn. Flexible products let you redeem quickly, usually with a lower and changing rate. Fixed or locked products pay a set rate for a set term, such as 30 or 90 days, and you cannot withdraw early, or you lose part of the interest.",["The yield comes from somewhere: ",["staking","staking"]," rewards on proof-of-stake coins, lending to margin traders or institutions, ",["liquidity","liquidity"]," provision or promotional budgets. Higher advertised rates often mean higher risk, a small cap per user, or a short promotional period."],["Your coins sit with the exchange, so this is custodial. If the platform has problems, earn balances can be frozen. Check whether rates are shown as ",["APR","apr-vs-apy"]," or APY, whether rewards are paid in the same coin, and the rules on redemption time. Products and availability differ by exchange and country."]],"example":["Suppose you deposit 5,000 ",["USDC","usdc"]," into a flexible product paying 4% APR, with interest credited daily. Daily interest is 5,000 times 0.04 divided by 365, about 0.55 USDC. Over 30 days you earn about 16.4 USDC if the rate stays the same. A 90-day locked product at 6% APR on the same amount would earn about 74 USDC, but your 5,000 USDC would be unavailable for those 90 days."],"mistakes":["Assuming advertised rates are fixed when flexible rates change frequently.","Locking funds you might need, and losing interest by redeeming early.","Forgetting that earn balances are held by the exchange, not in your own wallet."],"faq":[{"q":"Is Crypto Earn safe?","a":"It carries the risk of the exchange itself plus the risk of how the yield is generated. It is not a bank deposit and is usually not covered by deposit insurance."},{"q":"What is the difference between flexible and locked savings?","a":"Flexible savings let you withdraw at any time at a variable rate. Locked savings pay a set rate for a fixed term but restrict early withdrawal."}],"title":"What is Crypto Earn? Exchange savings explained","description":"What Crypto Earn savings products are, how flexible and locked terms differ, where the yield comes from and the custody risks.","related":[["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound."],["dual-investment","Dual investment","Dual investment is a structured exchange product where you earn a fixed yield but may be paid back in a different coin depending on whether the price ends above or below a target price on settlement."],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."]],"lesson":null,"coin":null,"tool":"/activities","cta":true},"p2p-trading":{"slug":"p2p-trading","cat":"exchange-features","en":"P2P (C2C) trading","contentLocale":"en","term":"P2P (C2C) trading","aka":["P2P","C2C","peer-to-peer trading","P2P exchange"],"short":"P2P (C2C) trading is buying or selling crypto directly with another user, paying in local money through bank transfer or payment apps while the platform holds the crypto in escrow.","body":["On an exchange's P2P marketplace, merchants post ads with a price, limits and accepted payment methods. When you place an order to buy, the seller's crypto is locked in escrow. You pay the seller directly by the agreed method, mark the order as paid, and the seller releases the crypto. Sellers follow the same steps in reverse.",["P2P is popular where bank deposits to exchanges are limited, and ",["stablecoins","stablecoin"]," like ",["USDT","usdt"]," are the most traded asset. Prices can be above or below the market rate, so compare ads. Many platforms charge no fee to takers, while merchants may pay one."],"Most problems come from payment disputes. Only release crypto after the money is actually in your account, not when a screenshot arrives. Never move the conversation or payment off the platform. Check that the payer's name matches the buyer's verified name; third-party payments can be linked to fraud and lead to frozen bank accounts. Rules and protections vary by exchange and country."],"example":"Suppose a merchant sells USDT at 1.02 local currency units and the market rate is 1.00. You buy 500 USDT and pay 510 units by bank transfer within the 15-minute window. The 10-unit difference, 2%, is the merchant's margin. If you had chosen an ad at 1.005, you would have paid 502.5 units, saving 7.5. After you mark the order as paid, the merchant releases 500 USDT from escrow to your funding account.","mistakes":["Releasing crypto as a seller after seeing a payment screenshot instead of checking your bank balance.","Agreeing to pay or chat outside the platform, which removes escrow protection.","Accepting payment from a bank account in a different name than the buyer's."],"faq":[{"q":"Is P2P crypto trading safe?","a":"Escrow protects the crypto side, but payment fraud is common. Stay on the platform, check payments yourself and trade with verified, experienced merchants."},{"q":"What does C2C mean in crypto?","a":"C2C means customer-to-customer and is another name used for P2P trading on some exchanges."}],"title":"What is P2P crypto trading? How C2C works","description":"How P2P (C2C) crypto trading works, how escrow protects orders, how merchant pricing works and how to avoid payment scams.","related":[["fiat-on-ramp","Fiat on-ramp","A fiat on-ramp is any service that turns government money like dollars or euros into crypto, such as a bank transfer to an exchange, a card purchase or a P2P trade."],["usdt","USDT (Tether)","USDT, also called Tether, is the largest US dollar stablecoin, issued by Tether, designed to stay at 1 dollar and backed by reserves the company reports in regular attestations."],["pig-butchering-scam","Pig-butchering scam","A pig-butchering scam is a long-con fraud where a stranger builds trust over weeks, often as a friend or romantic interest, then steers you into a fake crypto investment platform and takes everything you deposit."],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"First deposit: where does the money come from, and where does it go?"},"coin":null,"tool":null,"cta":true}});
